public struct Vault {                 // public type, internal members by default
    private let store: Store          // cannot appear in a public signature
    private let policy: Policy

    public func read(who: Subject, id: Id) throws -> Record {
        guard policy.allows(who, id) else { throw AccessError.denied(id) }
        return try store.load(id)     // the guard is the only route to store
    }
}
